do $c$begin if not exists(select 1 from pg_constraint where conname='presupuestos_encabezado_anio_check'and conrelid='public.presupuestos_encabezado'::regclass)then alter table public.presupuestos_encabezado add constraint "presupuestos_encabezado_anio_check" CHECK (((anio >= 2000) AND (anio <= 2199)));end if;end$c$;
